def time_band(hour):
    if hour < 6:
        return 'night'
    if hour < 12:
        return 'morning'
    if hour < 17:
        return 'afternoon'
    if hour < 21:
        return 'evening'
    return 'late_evening'

df['time_band'] = df['hour'].apply(time_band)

